using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

namespace Gtk4.PresentationFramework.Tests;

/// <summary>
/// Custom test entry point (<c>XunitAutoGeneratedEntryPoint</c> is disabled in the csproj).
/// Mirrors the entry point in Gtk4.Forms.Platform.Gtk.UnitTests: standard MTP path for
/// dotnet test/VS, thread-0 path for macOS (GTK 4 Quartz requires thread 0).
/// </summary>
static class Program
{
	const int WatchdogSeconds = 600;

	[STAThread]
	static int Main(string[] args)
	{
		if (args.Any(a => a == "--server" || a == "--internal-msbuild-node"))
			return global::Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework
				.RunAsync(args, SelfRegisteredExtensions.AddSelfRegisteredExtensions)
				.GetAwaiter().GetResult();

		bool threadZero = OperatingSystem.IsMacOS()
		                  || Environment.GetEnvironmentVariable("XF_GTK_MAC_RUNNER") == "1";

		if (!threadZero)
			return global::Xunit.Runner.InProc.SystemConsole.ConsoleRunner
				.Run(args).GetAwaiter().GetResult();

		return RunOnThreadZero(args);
	}

	static int RunOnThreadZero(string[] args)
	{
		WpfGtkThreadBridge.Queue = new BlockingCollection<Action>();

		int exit = 0;
		var finished = new ManualResetEventSlim();

		var worker = new Thread(() =>
			{
				try
				{
					exit = global::Xunit.Runner.InProc.SystemConsole.ConsoleRunner
						.Run(args).GetAwaiter().GetResult();
				}
				catch (Exception e)
				{
					Console.Error.WriteLine("MacRunner: the test runner crashed: " + e);
					exit = 1;
				}
				finally
				{
					WpfGtkThreadBridge.Queue!.CompleteAdding();
					finished.Set();
				}
			})
			{ IsBackground = true, Name = "xunit" };

		worker.Start();
		StartWatchdog(finished);
		WpfGtkThreadBridge.RunLoop();
		finished.Wait();
		return exit;
	}

	static void StartWatchdog(ManualResetEventSlim finished)
	{
		var watchdog = new Thread(() =>
			{
				// Each GTK test is one thread-0 work item, so a hang shows as no item starting or ending for the
				// limit; the suite as a whole may run longer than that on a slow runner.
				while (!finished.Wait(TimeSpan.FromSeconds(10)))
				{
					if (WpfGtkThreadBridge.IdleMilliseconds < WatchdogSeconds * 1000L) continue;
					Console.Error.WriteLine(
						$"MacRunner STALL: the GTK test run made no progress for {WatchdogSeconds}s.");
					Environment.Exit(3);
				}
			})
			{ IsBackground = true, Name = "watchdog" };
		watchdog.Start();
	}
}